  Future<SessionSweepReport> sweep({
    required bool dryRun,
    SessionUsageSnapshot? prebuilt,
  }) async {
    final usage = prebuilt ?? await this.usage();
    if (!retention.hasCap) {
      return _noOpReport(usage: usage, dryRun: dryRun, capConfigured: false);
