      final note =
          'retention: still over cap by '
          '${formatRetentionBytes(overflow)} — ${blockers.length} '
          'exempt session(s) hold ${formatRetentionBytes(held)}; '
          'nothing else is deletable';
      logLines.add(note);
      _emit(note);
