      dryRun: dryRun,
      capConfigured: true,
      totalBytes: usage.totalBytes,
      capBytes: cap,
      actions: [...deletions, ...blockers],
      rootFreedBytes: freed,
      spillFreedBytes: spillFreed,
      logLines: List.unmodifiable(logLines),
      notes: usage.notes,
      applied: applied,
