        // apply) lands in fa.log with the other lifecycle lines.
        log: (line) => _logDiagnostic('[retention] $line'),
      ).enforceAtBoot();
      final lines = sessionSweepReportLines(report);
      for (final line in lines) {
        _logDiagnostic('[retention] $line');
