    if (id is! String || cwd is! String || timestamp is! String) return null;
    final createdAt = DateTime.tryParse(timestamp);
    if (createdAt == null) return null;
    return _SessionHeaderFacts(id: id, cwd: cwd, createdAt: createdAt);
