  final bool cleanWorkspaceSpills;

  /// The posture-B soft-warn threshold (seam: tests shrink it; prod uses
  /// [retentionSoftWarnBytes]).
  final int softWarnBytes;

  void _emit(String line) {
    log?.call(line);
