    required String sessionsRoot,
    this.retention = const SessionRetentionConfig(),
    this.presenceStore,
    this.currentSessionId,
    DateTime Function()? now,
    this.log,
    this.cleanWorkspaceSpills = true,
    this.softWarnBytes = retentionSoftWarnBytes,
