    if (createdAt != null) {
      final raw = (await env.readTextFile(metadata.path)).valueOrNull!;
      await env.writeFile(
        metadata.path,
        raw.replaceFirst(
          RegExp(r'"timestamp":"[^"]+"'),
          '"timestamp":"${createdAt.toIso8601String()}"',
        ),
      );
    }
    env.setMtime(
      metadata.path,
      (lastUsed ?? createdAt ?? _clockNow).millisecondsSinceEpoch,
    );
