      final io = _CleanIo();
      final code = await runSessionCleanCliCommand(
        write: io.write,
        writeln: io.writeln,
        env: env,
        sessionRoot: '/sessions',
        now: _clock,
        retention: const SessionRetentionConfig(),
      );
      expect(code, 0);
      expect(io.buffer.toString(), contains('sessions.retention'));
      expect((await repo.list()), isNotEmpty);
    });
  });
}

