}) => SessionSweepReport(
  dryRun: dryRun,
  capConfigured: capConfigured,
  totalBytes: usage.totalBytes,
  capBytes: capBytes,
  actions: const [],
  rootFreedBytes: 0,
  spillFreedBytes: 0,

