      model: testModel,
      apiKey: '[REDACTED:Sensitive Value]',
      env: env,
      sessionRoot: '/sessions',
      providerKind: 'openai-completions',
      sessionName: sessionName,
      sessionsRetention: sessions,
      presenceStore: presence,
