void main() {
  late MemoryExecutionEnv env;
  late FakeCliIO bootIo;
  late JsonlSessionRepo repo;
  late FileSessionPresenceStore presence;

  setUp(() {
    env = MemoryExecutionEnv(cwd: '/work');
    bootIo = FakeCliIO();
    repo = JsonlSessionRepo(fs: env, sessionsRoot: '/sessions');
