    env = MemoryExecutionEnv(cwd: '/work');
    bootIo = FakeCliIO();
    repo = JsonlSessionRepo(fs: env, sessionsRoot: '/sessions');
    presence = FileSessionPresenceStore(env: env, root: '/sessions');
  });

