        await waitForIt(
          () => bareIo.out.toString().contains('switch:'),
          reason: 'the listing completes',
        );
        expect(bareIo.out.toString(), isNot(contains('total:')));
        expect(bareIo.out.toString(), isNot(contains('cap:')));
        bareIo.sendLine('/exit');
        await bareRun;
        await bareIo.close();
      },
    );

